PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, avatar TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE oauth_states (id TEXT PRIMARY KEY, verifier TEXT NOT NULL, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, project_id TEXT, expires_at INTEGER NOT NULL);
CREATE TABLE google_connections (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, encrypted_tokens TEXT NOT NULL, scopes TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE projects (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, domain TEXT NOT NULL, name TEXT NOT NULL, url TEXT NOT NULL, gsc_property TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_sync_at TEXT, UNIQUE(owner_id,domain));
CREATE INDEX projects_owner ON projects(owner_id,created_at);
CREATE TABLE tracked_keywords (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, keyword TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, UNIQUE(project_id,keyword));
CREATE TABLE gsc_performance (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, keyword TEXT NOT NULL, page TEXT NOT NULL, date TEXT NOT NULL, device TEXT NOT NULL, country TEXT NOT NULL, clicks REAL NOT NULL, impressions REAL NOT NULL, position REAL NOT NULL, synced_at TEXT NOT NULL, UNIQUE(project_id,keyword,page,date,device,country));
CREATE INDEX gsc_project_date ON gsc_performance(project_id,date,keyword);
CREATE TABLE backlink_import_batches (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE backlinks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, identity_key TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,identity_key));
CREATE TABLE domain_authority_cache (domain TEXT PRIMARY KEY, score REAL, fetched_at TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE backlink_risk_assessments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, backlink_id TEXT NOT NULL REFERENCES backlinks(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE project_toxicity_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE audit_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE crawled_pages (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, audit_id TEXT NOT NULL REFERENCES audit_runs(id) ON DELETE CASCADE, url TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, UNIQUE(audit_id,url));
CREATE TABLE page_audit_findings (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, audit_id TEXT NOT NULL REFERENCES audit_runs(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE pagespeed_results (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE seo_issues (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, fingerprint TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,fingerprint));
CREATE TABLE issue_comments (id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES seo_issues(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE issue_events (id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES seo_issues(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE background_jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('gsc','crawl','pagespeed','toxicity')), status TEXT NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','RUNNING','COMPLETED','FAILED','CANCELLED')), payload TEXT NOT NULL CHECK(json_valid(payload)), progress INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, lease_until INTEGER, lease_token TEXT, next_attempt INTEGER NOT NULL DEFAULT 0, last_error TEXT, dedupe_key TEXT, created_at TEXT NOT NULL, started_at TEXT, completed_at TEXT);
CREATE UNIQUE INDEX jobs_active_key ON background_jobs(project_id,dedupe_key) WHERE status IN ('QUEUED','RUNNING');
CREATE INDEX jobs_queue ON background_jobs(status,next_attempt,lease_until);
CREATE TABLE integration_sync_logs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL);
CREATE TABLE usage_budgets (scope TEXT NOT NULL, service TEXT NOT NULL, date TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(scope,service,date));
CREATE INDEX backlinks_project ON backlinks(project_id,updated_at);
CREATE INDEX batches_project ON backlink_import_batches(project_id,created_at);
CREATE INDEX risks_project ON backlink_risk_assessments(project_id,created_at);
CREATE INDEX toxicity_project ON project_toxicity_snapshots(project_id,created_at);
CREATE INDEX audits_project ON audit_runs(project_id,created_at);
CREATE INDEX pages_project ON crawled_pages(project_id,created_at);
CREATE INDEX findings_project ON page_audit_findings(project_id,created_at);
CREATE INDEX psi_project ON pagespeed_results(project_id,created_at);
CREATE INDEX issues_project ON seo_issues(project_id,updated_at);
CREATE INDEX comments_issue ON issue_comments(issue_id,created_at);
CREATE INDEX events_issue ON issue_events(issue_id,created_at);
CREATE INDEX logs_project ON integration_sync_logs(project_id,created_at);
